// Generated by Automated Quality Gate; review before merging.
const {
  add,
  subtract,
  multiply,
  divide,
  calculatePercentage,
  modulo,
  absoluteDifference
} = require('../src/math');

describe('math utility functions', () => {
  describe('add', () => {
    test('should correctly add two positive numbers', () => {
      expect(add(2, 3)).toBe(5);
    });

    test('should throw TypeError for non-number inputs', () => {
      expect(() => add(2, '3')).toThrow(TypeError);
    });
  });

  describe('subtract', () => {
    test('should correctly subtract two numbers', () => {
      expect(subtract(5, 3)).toBe(2);
    });

    test('should return 0 instead of -0', () => {
      expect(subtract(0, 0)).toBe(0);
    });
  });

  describe('multiply', () => {
    test('should correctly multiply two numbers', () => {
      expect(multiply(4, 5)).toBe(20);
    });

    test('should throw TypeError for infinite numbers', () => {
      expect(() => multiply(2, Infinity)).toThrow('Inputs must be finite numbers');
    });
  });

  describe('divide', () => {
    test('should correctly divide two numbers', () => {
      expect(divide(10, 2)).toBe(5);
    });

    test('should throw Error when dividing by zero', () => {
      expect(() => divide(10, 0)).toThrow('Cannot divide by zero');
    });
  });

  describe('calculatePercentage', () => {
    test('should calculate percentage correctly', () => {
      expect(calculatePercentage(50, 200)).toBe(25);
    });

    test('should return 0 when total is 0', () => {
      expect(calculatePercentage(50, 0)).toBe(0);
    });
  });

  describe('modulo', () => {
    test('should calculate correct modulo', () => {
      expect(modulo(10, 3)).toBe(1);
    });

    test('should throw Error for modulo by zero', () => {
      expect(() => modulo(10, 0)).toThrow('Cannot modulo by zero');
    });
  });

  describe('absoluteDifference', () => {
    test('should return the absolute difference', () => {
      expect(absoluteDifference(5, 10)).toBe(5);
      expect(absoluteDifference(10, 5)).toBe(5);
    });

    test('should throw TypeError for NaN inputs', () => {
      expect(() => absoluteDifference(5, NaN)).toThrow('Inputs must be valid numbers');
    });
  });
});
